var promptLibrary={"id":"prompt-library-pcl","name":"Biblioteca de Prompts PC&L","desc":"Biblioteca moderna para consultar e copiar prompts operacionais com titulo e objetivo de uso.","category":"Prompt","status":"Disponível","url":"","instruction":"","links":[{"name":"Inventory Optimization","purpose":"Analisa desvios de inventario versus a meta JNI e recomenda acoes para melhorar DIO e controle de estoque.","prompt":"Act as an experienced PC&L Material Planner. I am working to improve DIO and achieve JNI inventory targets. Explain possible reasons for a gap between current inventory performance and JNI target, identify inventory risks, and recommend actions related to planning, supplier management, inventory control, forecast accuracy, and order policies."},{"name":"Template Painel HTML","purpose":"Gera um template Control Tower responsivo e pronto para personalizar em sites do SharePoint.","prompt":"Crie um arquivo HTML único, responsivo e pronto para ser usado em qualquer site do SharePoint como um painel de navegação operacional.\n\nObjetivo:\n- Criar um template genérico de “Control Tower” que possa ser personalizado por qualquer área.\n- Não usar dependências externas, CDN, imagens externas ou bibliotecas.\n- Incluir todo CSS e JavaScript no próprio arquivo HTML.\n- Usar textos em português e campos de exemplo fáceis de substituir.\n\nLayout:\n- Barra lateral esquerda azul-escura, recolhida por padrão, exibindo uma sigla.\n- Ao passar o mouse, expandir a barra lateral e mostrar:\n  - Nome da empresa\n  - Nome da área/setor\n  - Menu “Navegação”\n  - Botões “Visão geral” e “Categoria”\n  - Rodapé “Template padrão / Control Tower”\n- Área principal com:\n  - Título do painel\n  - Descrição curta\n  - Botão “+ Adicionar item”\n  - Quatro cards de indicadores com rótulo, valor e texto auxiliar\n  - Banner principal com resumo da operação e campo para sigla\n  - Seção “Itens em destaque” com cards para recursos, links ou orientações\n  - Seção “Categoria” com cabeçalho, descrição e cards de recursos\n- Os botões do menu devem alternar entre as seções “Visão geral” e “Categoria”, ocultando a seção não selecionada.\n- Os botões e cards podem ser visuais, sem necessidade de persistência de dados.\n\nEstilo:\n- Visual corporativo, limpo e moderno.\n- Paleta: azul-marinho, azul-petróleo, vermelho como cor de destaque, branco e cinza-claro.\n- Cards com bordas arredondadas, sombra leve e boa legibilidade.\n- Layout responsivo:\n  - Desktop: barra lateral fixa e cards em grade.\n  - Tablet: indicadores e cards em duas colunas.\n  - Celular: uma coluna, barra lateral expandida e sem efeito de recolhimento.\n- Usar fonte Segoe UI, com alternativas seguras.\n- Incluir comentários no HTML indicando quais textos, cores, indicadores, categorias e links podem ser alterados.\n\nEntregue somente o conteúdo completo do arquivo HTML, iniciado por ."},{"name":"Apresentação Gerencial Nexteer","purpose":"Cria uma apresentação gerencial em PowerPoint com pesquisa restrita às fontes internas autorizadas e identidade visual Nexteer.","prompt":"Objetivo e público\nObjetivo: [O QUE QUERO INFORMAR OU QUAL DECISÃO PRECISO APOIAR].\nPúblico: [EQUIPE, GESTÃO, DIRETORIA OU CLIENTE].\nIdioma: [PORTUGUÊS OU INGLÊS].\nQuantidade total de slides: [NÚMERO].\nTópicos obrigatórios: [LISTAR OS ASSUNTOS].\nPeríodo das informações: [DATA INICIAL E FINAL].\n\nPesquisa nas fontes internas\nPesquise informações às quais tenho acesso, limitando o conteúdo às seguintes fontes:\nTeams: equipe [NOME], canal ou chat [NOME E LINK].\nE-mails: mensagens de/para [PESSOAS OU GRUPO], sobre [ASSUNTOS E PALAVRAS-CHAVE].\nSharePoint: site [LINK], biblioteca ou pasta [NOME/LINK], arquivos prioritários [NOMES OU LINKS].\nConfirme que os resultados pertencem aos locais indicados. Não use informações de outros grupos ou projetos apenas porque têm nomes semelhantes. Se não conseguir acessar ou identificar uma fonte, informe a limitação e peça orientação antes de ampliar a pesquisa.\nPriorize documentos oficiais e atualizações recentes. Cruze as fontes para identificar resultados, indicadores, decisões, riscos e pendências. Diferencie propostas de decisões aprovadas. Não invente números, prazos ou responsáveis. Destaque divergências e informações não encontradas. Registre as fontes e suas datas nas notas dos slides correspondentes.\n\nIdentidade visual e imagens\nUse o PPT aberto/anexado como referência de composição e qualidade visual. Preserve o padrão Nexteer presente no material, incluindo cores, tipografia, logotipo e rodapés. Se houver um template oficial nas fontes indicadas, use-o como referência principal da marca.\nCrie slides com imagens bem desenvolvidas, relevantes para cada tópico e integradas ao layout. Priorize fotos e materiais corporativos disponíveis nas fontes autorizadas. Quando necessário, use imagens geradas como ilustrações, sem apresentá-las como registros reais de instalações, equipamentos ou operações da Nexteer.\nEvite imagens genéricas, distorções, excesso de texto e elementos sobrepostos. Mantenha textos, tabelas e gráficos editáveis, com boa legibilidade.\n\nOrganização do conteúdo\nDistribua os tópicos em uma narrativa clara: contexto, situação atual, evidências, pontos de atenção e próximos passos. Adapte essa estrutura ao tema e à quantidade de slides. Inclua responsáveis e prazos somente quando as fontes os confirmarem.\nAntes de criar os slides, apresente um roteiro curto com os títulos propostos e as fontes encontradas para eu aprovar. Pergunte apenas o que estiver faltando e afetar o resultado."}]};var promptExisting=dashboards.filter(function(d){return d.id==='prompt-library-pcl';})[0];if(promptExisting){promptExisting.name=promptLibrary.name;promptExisting.desc=promptLibrary.desc;promptExisting.category=promptLibrary.category;promptExisting.status=promptLibrary.status;promptExisting.links=promptExisting.links||[];promptExisting.links[0]=promptLibrary.links[0];promptExisting.links[1]=promptLibrary.links[1];}el