   +'<div class="sub-list">'+d.links.slice().sort(function(a,b){return a.name.localeCompare(b.name,'pt-BR',{sensitivity:'base'});}).map(function(x){var i=d.links.indexOf(x);return '<div class="report-row"><a class="report-link" href="'+esc(safeUrl(x.url)||'#')+'" target="_blank" rel="noopener noreferrer">'+portalIcon({name:x.name,url:x.url,links:[x]})+'<b>'+esc(x.name)+'</b>'+icon('external')+'</a><button type="button" class="row-btn" data-sub-edit="'+i+'" aria-label="'+tr('Editar')+' '+esc(x.name)+'" title="'+tr('Editar')+'">'+icon('pencil')+'</button><button type="button" class="row-btn del" data-sub-del="'+i+'" aria-label="'+tr('Excluir')+' '+esc(x.name)+'" title="'+tr('Excluir')+'">'+icon('trash')+'</button></div>';}).join('')+'</div>';
