 function emptyState(t,s){return '<div class="alerts-empty">'+icon('check')+'<b>'+esc(t)+'</b><small>'+esc(s)+'</small></div>';}
 function editFromSheet(e){var b=e.target.closest('[data-pending-edit]');if(b){sheet.close();openForm(b.getAttribute('data-pending-edit'));}}
 function openPending(){var list=insights().pending;sheet.open({ico:'alert',title:tr('Links pendentes'),sub:tr('Painéis que ainda não têm um link configurado.'),body:list.length?pendingListHtml(list,categoryLabel):emptyState(tr('Tudo configurado'),tr('Todos os painéis já têm link.')),onClick:editFromSheet});}
 function openUnused(){var used=new Set(panelStats.map(function(x){return x.panel_id;})),list=dashboards.filter(function(d){return !used.has(d.id);});sheet.open({ico:'trend',title:tr('Painéis sem acesso'),sub:tr('Ainda não foram abertos desde que o ranking começou. Avalie se ainda são necessários.'),body:list.length?pendingListHtml(list,categoryLabel):emptyState(tr('Tudo em uso'),tr('Todos os painéis já foram abertos.')),onClick:editFromSheet});}
 function reloadShared(){Promise.all([fetchCategories(),fetchPanels(),fetchTasks()]).then(function(r){categories=r[0];if(r[1])dashboards=r[1];if(r[2])tasks=r[2];dashboards.forEach(normalizePanel);saveCache();renderNav();render();}).catch(function(){showToast(tr('Não foi possível atualizar. Recarregue a página.'),true);});}
 function openTrashSheet(){openTrash(sheet,{showToast:showToast,onRestored:function(kind){if(kind==='event')calendar.reload();else reloadShared();}});}
 alerts=createNotifications(document.getElementById('bellBtn'),function(){return buildAlerts(insights(),{timeLabel:calendar.timeLabel,calendarCategory:CALENDAR_CATEGORY,taskCategory:TASK_CATEGORY});},{openEvent:function(id,day){calendar.openEvent(id,day);},goTo:goTo,openPanel:function(id){var d=findPanel(id);if(d)goTo(d.category);},openPending:openPending});
 var presenter=createPresentation({getSlides:function(){return presentSlides(insights(),{stats:panelStats,dashboards:dashboards,categoryLabel:categoryLabel,timeLabel:calendar.timeLabel});},getSeconds:function(){return prefs.get().presentSeconds;}});
 document.getElementById('presentBtn').onclick=function(){presenter.start();};
 document.getElementById('trashBtn').onclick=openTrashSheet;
 document.getElementById('prefsBtn').onclick=function(){prefs.open();};
 dock=mountDock({onHome:function(){goTo('Todos');},onSearch:function(){palette.open();},onCalendar:function(){goTo(CALENDAR_CATEGORY);},onAlerts:function(){alerts.open();},isActive:function(k){return k==='home'?filter==='Todos':k==='calendar'?filter===CALENDAR_CATEGORY:false;}});
 document.getElementById('sortSelect').onchange=function(){sortMode=this.value;try{localStorage.setItem(SORT_KEY,sortMode);}catch(e){}render();};
 document.getElementById('bulkBtn').onclick=function(){bulkMode=!bulkMode;bulkSel.clear();render();};
 grid.addEventListener('click',function(e){if(!bulkMode)return;var c=e.target.closest('.card.bulk');if(!c||e.target.closest('a,button,.bulk-check'))return;toggleBulk(c.getAttribute('data-card'));});
 grid.addEventListener('change',function(e){var cb=e.target.closest('[data-bulk]');if(cb)toggleBulk(cb.getAttribute('data-bulk'),cb.checked);});
 function toggleBulk(id,on){if(on===undefined)on=!bulkSel.has(id);if(on)bulkSel.add(id);else bulkSel.delete(id);var c=grid.querySelector('[data-card="'+CSS.escape(id)+'"]');if(c){c.classList.toggle('selected',on);var cb=c.querySelector('[data-bulk]');if(cb)cb.checked=on;}syncBulkBar();}
 function bulkPanels(){return dashboards.filter(function(d){return bulkSel.has(d.id);});}
 document.getElementById('bulkAll').onclick=function(){Array.prototype.forEach.call(grid.querySelectorAll('[data-card]'),function(c){bulkSel.add(c.getAttribute('data-card'));});render();};
 document.getElementById('bulkCancel').onclick=function(){bulkMode=false;bulkSel.clear();render();};
 document.getElementById('bulkMove').onclick=function(){var sel=document.getElementById('bulkTarget'),target=sel.value,list=bulkPanels();if(!target||!list.length)return;list.forEach(function(d){d.category=target;});bulkMode=false;bulkSel.clear();saveCache();renderNav();render();Promise.all(list.map(savePanel)).then(function(){showToast(tr(list.length===1?'{0} painel movido para {1}.':'{0} painéis movidos para {1}.',list.length,categoryLabel(target)));}).catch(function(){showToast(tr('Não foi possível salvar. Verifique a conexão e tente novamente.'),true);});};
 document.getElementById('bulkDelete').onclick=function(){var list=bulkPanels();if(!list.length)return;confirmAction(tr('Excluir painéis'),tr(list.length===1?'{0} painel será movido para a lixeira por 30 dias.':'{0} painéis serão movidos para a lixeira por 30 dias.',list.length),function(){var ids=new Set(list.map(function(d){return d.id;}));Promise.all(list.map(function(d){return deletePanel(d.id);})).then(function(){dashboards=dashboards.filter(function(d){return !ids.has(d.id);});bulkMode=false;bulkSel.clear();saveCache();renderNav();render();showToast(tr('Painéis movidos para a lixeira.'));}).catch(function(){reloadShared();showToast(tr('Alguns painéis não puderam ser excluídos. Tente novamente.'),true);});});};
 document.getElementById('bulkTarget').onfocus=function(){var sel=this,v=sel.value;sel.innerHTML='<option value="">'+tr('Mover para...')+'</option>'+sortedCategories().filter(function(c){return c.name!=='Instrução'&&c.name!==CALENDAR_CATEGORY;}).map(function(c){return '<option value="'+esc(c.name)+'">'+esc(tr(c.label))+'</option>';}).join('');sel.value=v;};
 document.getElementById('bulkTarget').onfocus();
 maybeSplash(prefs.get().splash,greeting());
 var startApplied=false;function applyStart(){if(startApplied)return;startApplied=true;var st=prefs.get().start,t='';if(st==='last'){try{t=localStorage.getItem('ct-last-area')||'';}catch(e){}}else if(st.indexOf('cat:')===0)t=st.slice(4);if(t&&t!=='Todos'&&categories.some(function(c){return c.name===t;}))goTo(t);}
 var sideBtn=document.getElementById('sideToggle');
 function setSide(c){document.body.classList.toggle('side-collapsed',c);sideBtn.setAttribute('aria-expanded',String(!c));var l=tr(c?'Expandir menu':'Recolher menu');sideBtn.title=l;sideBtn.setAttribute('aria-label',l);sideBtn.querySelector('.nav-txt').textContent=l;}
 sideBtn.onclick=function(){var c=!document.body.classList.contains('side-collapsed');setSide(c);try{localStorage.setItem('ct-side',c?'collapsed':'open');}catch(e){}};
 try{document.body.classList.toggle('side-collapsed',localStorage.getItem('ct-side')==='collapsed');}catch(e){}
 Array.prototype.forEach.call(document.querySelectorAll('[data-view-mode]'),function(b){b.onclick=function(){setViewMode(b.getAttribute('data-view-mode'));};});
 grid.addEventListener('pointermove',function(e){var c=e.target.closest&&e.target.closest('.card,.area-card');if(!c)return;var r=c.getBoundingClientRect();c.style.setProperty('--mx',(e.clientX-r.left)+'px');c.style.setProperty('--my',(e.clientY-r.top)+'px');});
 setLang(getLang());applyLanguage();
 // Show the last copy saved in this browser right away, then refresh from the shared database.
 var cached=readCache();
 if(cached){categories=cached.categories;dashboards=cached.dashboards;tasks=cached.tasks;dashboards.forEach(normalizePanel);renderNav();render();applyStart();}else grid.innerHTML='<div class="skeleton-grid" role="status" aria-label="'+tr('Carregando painéis...')+'">'+'<div class="skel-card"><span class="skel-ico"></span><span class="skel-line w60"></span><span class="skel-line"></span><span class="skel-line w80"></span><span class="skel-btn"></span></div>'.repeat(6)+'</div>';
 try{var freshCats=await fetchCategories(),loaded=await fetchPanels(),freshPanels=loaded||buildInitialDashboards();if(!loaded)await seedPanels(freshPanels);var loadedTasks=await fetchTasks(),freshTasks=loadedTasks?loadedTasks:await createTasks(buildInitialTasks());categories=freshCats;dashboards=freshPanels;tasks=freshTasks;}catch(e){if(cached){showToast(tr('Sem conexão. Mostrando a última versão salva neste navegador.'),true);return;}grid.innerHTML='<div class="load-state error">'+tr('Não foi possível carregar os painéis. Recarregue a página para tentar novamente.')+'</div>';return;}
 dashboards.forEach(normalizePanel);saveCache();renderNav();render();applyStart();loadStats();
